# Teardown Stage 4 microservices stack
Write-Host "Stopping Stage 4 microservices stack..."
if (Test-Path "stage4-pids.json") {
    $Pids = Get-Content -Raw -Path "stage4-pids.json" | ConvertFrom-Json
